import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    x = int(data[1])
    y = int(data[2])

    ans = y * n / 100.0 - x
    if ans < 0:
        ans = 0

    if ans == int(ans):
        print(int(ans))
    else:
        print(int(ans) + 1)

if __name__ == "__main__":
    main()

